def countBstsWithHeight(n, h):
    M = 1000000007
    h = min(h, n)
    prev = [1] + [0] * n          # height at most 0: only the empty tree
    for _ in range(h):
        cur = [1] + [0] * n
        for k in range(1, n + 1):
            s = 0
            for i in range(k):
                if prev[i]:
                    s += prev[i] * prev[k - 1 - i]
            cur[k] = s % M
        prev = cur
    return prev[n]
